-- Slice 23: Recurring invoices (/{slug}/recurring-invoices) and Recurring bills (/{slug}/recurring-bills),
-- modelled on lejar.ai (i18n bundle + help articles, docs/re/23-recurring.md).
-- Also adds record_draft_bill / delete_draft_bill so draft bills generated by recurring templates can be reviewed and posted.

-- Allow 'exempt' on invoice_lines (matching bill_lines, quote_lines, delivery_order_lines, sales_note_lines).
alter table public.invoice_lines drop constraint if exists invoice_lines_tax_code_check;
alter table public.invoice_lines add constraint invoice_lines_tax_code_check
  check (tax_code in ('none', 'sst_6', 'sst_8', 'sales_5', 'sales_10', 'exempt'));

-- ---------------------------------------------------------------------------------------------
-- Draft bill posting & deletion (for recurring bills left as draft for review).
create function public.post_draft_bill(p_org uuid, p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  b public.bills;
  v_je_lines jsonb := '[]';
  r record;
  v_tax_acct uuid;
  v_je uuid;
begin
  select * into b from public.bills where id = p_id and org_id = p_org for update;
  if b.id is null or b.status <> 'draft' then
    raise exception 'not_draft' using errcode = '22023';
  end if;
  perform public.assert_open_period(p_org, b.bill_date);

  for r in select account_id, description, amount from public.bill_lines where bill_id = p_id order by line_no loop
    if r.amount > 0 then
      v_je_lines := v_je_lines || jsonb_build_object(
        'accountId', r.account_id, 'debit', r.amount, 'description', left(coalesce(r.description, b.bill_number), 200));
    end if;
  end loop;
  if b.tax_total > 0 then
    v_tax_acct := public.account_id_for(p_org, '400-1400');
    v_je_lines := v_je_lines || jsonb_build_object('accountId', v_tax_acct, 'debit', b.tax_total, 'description', 'SST Input Tax');
  end if;
  v_je_lines := v_je_lines || jsonb_build_object('accountId', b.payable_account_id, 'credit', b.total, 'description', b.bill_number);

  v_je := public.insert_journal(p_org, null, b.bill_date, 'Bill ' || b.bill_number, 'bill', p_id, b.source_document_id, b.ai_draft_id, v_je_lines);
  update public.bills set status = 'open', journal_entry_id = v_je where id = p_id;
end;
$$;
revoke all on function public.post_draft_bill(uuid, uuid) from public, anon, authenticated;

create function public.record_draft_bill(p_slug text, p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.post_draft_bill(public.learn_org_for_editor(p_slug), p_id);
end;
$$;

create function public.delete_draft_bill(p_slug text, p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_org uuid := public.learn_org_for_editor(p_slug);
begin
  delete from public.bills where id = p_id and org_id = v_org and status = 'draft';
  if not found then raise exception 'only_draft_delete' using errcode = '22023'; end if;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Recurring templates, lines, and run ledger.
create table public.recurring_templates (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  kind text not null check (kind in ('invoice', 'bill')),
  name text not null check (char_length(name) between 2 and 120),
  contact_id uuid not null references public.contacts (id),
  frequency text not null check (frequency in ('weekly', 'monthly', 'quarterly', 'yearly')),
  interval_count integer not null default 1 check (interval_count between 1 and 36),
  start_date date not null,
  end_date date,
  occurrences_limit integer check (occurrences_limit is null or occurrences_limit between 1 and 999),
  occurrences_generated integer not null default 0 check (occurrences_generated >= 0),
  next_run_on date,
  due_offset_days integer not null default 30 check (due_offset_days between 0 and 365),
  number_prefix text not null check (char_length(number_prefix) between 1 and 30),
  auto_record boolean not null default false,
  notes text check (notes is null or char_length(notes) <= 1000),
  status text not null default 'active' check (status in ('active', 'paused', 'completed', 'cancelled')),
  subtotal numeric(14, 2) not null default 0,
  tax_total numeric(14, 2) not null default 0,
  total numeric(14, 2) not null default 0,
  created_by uuid not null references auth.users (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_date is null or end_date >= start_date)
);

-- lejar.ai prefix rules: unique per org for invoices; unique per (org, supplier) for bills.
create unique index recurring_invoices_prefix_uidx
  on public.recurring_templates (org_id, lower(number_prefix))
  where kind = 'invoice' and status <> 'cancelled';

create unique index recurring_bills_prefix_uidx
  on public.recurring_templates (org_id, contact_id, lower(number_prefix))
  where kind = 'bill' and status <> 'cancelled';

create index recurring_templates_org_kind_idx on public.recurring_templates (org_id, kind, status, next_run_on);

create table public.recurring_template_lines (
  template_id uuid not null references public.recurring_templates (id) on delete cascade,
  line_no integer not null,
  org_id uuid not null references public.organizations (id) on delete cascade,
  description text not null check (char_length(description) between 1 and 500),
  account_id uuid not null references public.accounts (id),
  amount numeric(14, 2) not null check (amount > 0),
  tax_code text not null default 'none' check (tax_code in ('none', 'sst_6', 'sst_8', 'sales_5', 'sales_10', 'exempt')),
  tax_amount numeric(14, 2) not null default 0,
  primary key (template_id, line_no)
);

create table public.recurring_runs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  template_id uuid not null references public.recurring_templates (id) on delete cascade,
  kind text not null check (kind in ('invoice', 'bill')),
  scheduled_on date not null,
  status text not null check (status in ('draft', 'recorded', 'failed')),
  invoice_id uuid references public.invoices (id) on delete set null,
  bill_id uuid references public.bills (id) on delete set null,
  doc_number text,
  error text,
  ran_at timestamptz not null default now()
);

-- Guarantees idempotency: an occurrence already generated is never billed/invoiced twice.
create unique index recurring_runs_once_uidx
  on public.recurring_runs (template_id, scheduled_on)
  where status in ('draft', 'recorded');

create index recurring_runs_org_kind_idx on public.recurring_runs (org_id, kind, ran_at desc);

do $$
declare t text;
begin
  foreach t in array array['recurring_templates', 'recurring_template_lines', 'recurring_runs'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy "%s: members read" on public.%I for select to authenticated using (public.is_org_member(org_id))', t, t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Schedule date arithmetic (anchored to start_date so 31st-of-month schedules don't drift).
create function public.recurring_next_date(p_start date, p_freq text, p_every int, p_step int) returns date
language sql immutable as $$
  select case p_freq
    when 'weekly' then p_start + (p_every * p_step * 7)
    when 'monthly' then (p_start + make_interval(months => p_every * p_step))::date
    when 'quarterly' then (p_start + make_interval(months => p_every * p_step * 3))::date
    when 'yearly' then (p_start + make_interval(years => p_every * p_step))::date
  end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Create a recurring invoice or bill template.
create function public.create_recurring_template(p_slug text, p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := public.learn_org_for_editor(p_slug);
  v_kind text := coalesce(p->>'kind', '');
  v_name text := btrim(coalesce(p->>'name', ''));
  v_contact uuid := nullif(p->>'contactId', '')::uuid;
  v_contact_name text := nullif(btrim(coalesce(p->>'contactName', '')), '');
  v_contact_kind text;
  v_freq text := coalesce(p->>'frequency', 'monthly');
  v_every int := coalesce(nullif(p->>'intervalCount', '')::int, 1);
  v_start date := nullif(p->>'startDate', '')::date;
  v_end date := nullif(p->>'endDate', '')::date;
  v_limit int := nullif(p->>'occurrencesLimit', '')::int;
  v_due int := coalesce(nullif(p->>'dueOffsetDays', '')::int, 30);
  v_prefix text := btrim(coalesce(p->>'numberPrefix', ''));
  v_auto boolean := coalesce((p->>'autoRecord')::boolean, false);
  v_notes text := nullif(btrim(coalesce(p->>'notes', '')), '');
  v_id uuid;
  v_line jsonb;
  v_n int := 0;
  v_acct record;
  v_amt numeric;
  v_tax_code text;
  v_tax numeric;
  v_sub numeric := 0;
  v_tax_total numeric := 0;
begin
  if v_kind not in ('invoice', 'bill') then raise exception 'invalid_kind' using errcode = '22023'; end if;
  if char_length(v_name) < 2 then raise exception 'template_name_short' using errcode = '22023'; end if;
  if char_length(v_name) > 120 then raise exception 'template_name_long' using errcode = '22023'; end if;
  if v_freq not in ('weekly', 'monthly', 'quarterly', 'yearly') then raise exception 'invalid_frequency' using errcode = '22023'; end if;
  if v_every < 1 or v_every > 36 then raise exception 'invalid_every' using errcode = '22023'; end if;
  if v_start is null then raise exception 'start_date_required' using errcode = '22023'; end if;
  if v_end is not null and v_end < v_start then raise exception 'end_before_start' using errcode = '22023'; end if;
  if v_limit is not null and (v_limit < 1 or v_limit > 999) then raise exception 'invalid_occurrences' using errcode = '22023'; end if;
  if v_due < 0 or v_due > 365 then raise exception 'invalid_due_offset' using errcode = '22023'; end if;
  if char_length(v_prefix) < 1 or char_length(v_prefix) > 30 then raise exception 'prefix_required' using errcode = '22023'; end if;
  if jsonb_typeof(p->'lines') <> 'array' or jsonb_array_length(p->'lines') = 0 then
    raise exception 'add_line' using errcode = '22023';
  end if;

  if v_contact is not null then
    select kind into v_contact_kind from public.contacts where id = v_contact and org_id = v_org;
    if v_contact_kind is null then raise exception 'contact_missing' using errcode = '22023'; end if;
    if v_kind = 'invoice' and v_contact_kind not in ('customer', 'both') then
      raise exception 'not_customer' using errcode = '22023';
    end if;
    if v_kind = 'bill' and v_contact_kind not in ('supplier', 'both') then
      raise exception 'not_supplier' using errcode = '22023';
    end if;
  elsif v_contact_name is not null then
    select id, kind into v_contact, v_contact_kind from public.contacts where org_id = v_org and lower(name) = lower(v_contact_name);
    if v_contact is null then
      insert into public.contacts (org_id, name, kind)
      values (v_org, left(v_contact_name, 200), case when v_kind = 'invoice' then 'customer' else 'supplier' end)
      returning id into v_contact;
    elsif (v_kind = 'invoice' and v_contact_kind = 'supplier') or (v_kind = 'bill' and v_contact_kind = 'customer') then
      update public.contacts set kind = 'both' where id = v_contact;
    end if;
  else
    raise exception 'pick_contact' using errcode = '22023';
  end if;

  insert into public.recurring_templates (
    org_id, kind, name, contact_id, frequency, interval_count, start_date, end_date,
    occurrences_limit, next_run_on, due_offset_days, number_prefix, auto_record, notes, created_by
  )
  values (
    v_org, v_kind, v_name, v_contact, v_freq, v_every, v_start, v_end,
    v_limit, v_start, v_due, v_prefix, v_auto, left(v_notes, 1000), auth.uid()
  )
  returning id into v_id;

  for v_line in select * from jsonb_array_elements(p->'lines') loop
    v_n := v_n + 1;
    if nullif(btrim(coalesce(v_line->>'description', '')), '') is null then
      raise exception 'line_description' using errcode = '22023';
    end if;
    select id, code, type, status into v_acct
    from public.accounts where org_id = v_org and code = btrim(coalesce(v_line->>'accountCode', ''));
    if v_acct.id is null then
      raise exception 'account_missing' using errcode = '22023', detail = coalesce(v_line->>'accountCode', '');
    end if;
    if v_acct.status <> 'active' then
      raise exception 'account_inactive' using errcode = '22023', detail = v_acct.code;
    end if;
    if v_kind = 'invoice' and v_acct.type <> 'revenue' then
      raise exception 'account_type' using errcode = '22023', detail = v_acct.code;
    end if;
    if v_kind = 'bill' and v_acct.type not in ('expense', 'asset') then
      raise exception 'account_type' using errcode = '22023', detail = v_acct.code;
    end if;
    v_amt := round(nullif(v_line->>'amount', '')::numeric, 2);
    if v_amt is null or v_amt <= 0 then
      raise exception 'line_amount' using errcode = '22023';
    end if;
    v_tax_code := coalesce(nullif(v_line->>'taxCode', ''), 'none');
    if v_tax_code not in ('none', 'sst_6', 'sst_8', 'sales_5', 'sales_10', 'exempt') then
      v_tax_code := 'none';
    end if;
    v_tax := round(v_amt * public.tax_rate(v_tax_code), 2);
    insert into public.recurring_template_lines (template_id, line_no, org_id, description, account_id, amount, tax_code, tax_amount)
    values (v_id, v_n, v_org, left(btrim(v_line->>'description'), 500), v_acct.id, v_amt, v_tax_code, v_tax);
    v_sub := v_sub + v_amt;
    v_tax_total := v_tax_total + v_tax;
  end loop;

  update public.recurring_templates set subtotal = v_sub, tax_total = v_tax_total, total = v_sub + v_tax_total where id = v_id;
  return v_id;
exception
  when unique_violation then
    raise exception 'duplicate_prefix' using errcode = '23505';
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Pause / Resume / Cancel a template.
create function public.set_recurring_status(p_slug text, p_id uuid, p_status text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := public.learn_org_for_editor(p_slug);
  t public.recurring_templates;
begin
  select * into t from public.recurring_templates where id = p_id and org_id = v_org for update;
  if not found then raise exception 'template_not_found' using errcode = '22023'; end if;

  if p_status = 'paused' then
    if t.status <> 'active' then raise exception 'not_active' using errcode = '22023', detail = 'paused'; end if;
    update public.recurring_templates set status = 'paused', updated_at = now() where id = t.id;
  elsif p_status = 'active' then
    if t.status <> 'paused' then raise exception 'not_paused' using errcode = '22023', detail = 'active'; end if;
    update public.recurring_templates set status = 'active', updated_at = now() where id = t.id;
  elsif p_status = 'cancelled' then
    if t.status not in ('active', 'paused') then
      raise exception 'not_active' using errcode = '22023', detail = 'cancelled';
    end if;
    update public.recurring_templates set status = 'cancelled', next_run_on = null, updated_at = now() where id = t.id;
  else
    raise exception 'invalid_status' using errcode = '22023';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Generate every due invoice or bill on or before p_as_of (idempotent; safe to re-run).
create function public.generate_due_recurring(p_slug text, p_kind text, p_as_of date default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_org uuid := public.learn_org_for_editor(p_slug);
  v_today date := coalesce(p_as_of, (now() at time zone 'Asia/Kuala_Lumpur')::date);
  t public.recurring_templates;
  v_evaluated int := 0;
  v_generated int := 0;
  v_recorded int := 0;
  v_failed int := 0;
  v_guard int;
  v_run_date date;
  v_due_date date;
  v_doc_num text;
  v_lines jsonb;
  v_doc_id uuid;
  v_ap uuid;
  v_trade text;
  v_next_count int;
  v_next_date date;
  v_new_status text;
  v_err text;
begin
  if p_kind not in ('invoice', 'bill') then raise exception 'invalid_kind' using errcode = '22023'; end if;

  for t in
    select * from public.recurring_templates
    where org_id = v_org and kind = p_kind and status = 'active' and next_run_on is not null and next_run_on <= v_today
    order by next_run_on, created_at
    for update
  loop
    v_evaluated := v_evaluated + 1;
    v_guard := 0;
    v_run_date := t.next_run_on;
    v_next_count := t.occurrences_generated;

    while v_run_date is not null and v_run_date <= v_today and v_guard < 60 loop
      v_guard := v_guard + 1;

      -- Idempotency check: if already generated for this scheduled date, advance schedule without duplicating.
      if exists (
        select 1 from public.recurring_runs
        where template_id = t.id and scheduled_on = v_run_date and status in ('draft', 'recorded')
      ) then
        v_next_count := v_next_count + 1;
        v_next_date := public.recurring_next_date(t.start_date, t.frequency, t.interval_count, v_next_count);
        if (t.occurrences_limit is not null and v_next_count >= t.occurrences_limit) or (t.end_date is not null and v_next_date > t.end_date) then
          v_run_date := null;
          v_new_status := 'completed';
        else
          v_run_date := v_next_date;
          v_new_status := 'active';
        end if;
        update public.recurring_templates
        set occurrences_generated = v_next_count, next_run_on = v_run_date, status = v_new_status, updated_at = now()
        where id = t.id;
        continue;
      end if;

      v_due_date := v_run_date + t.due_offset_days;
      v_doc_num := case
        when right(t.number_prefix, 1) in ('-', '/', '_') then t.number_prefix || to_char(v_run_date, 'YYYY-MM-DD')
        else t.number_prefix || '-' || to_char(v_run_date, 'YYYY-MM-DD')
      end;

      begin
        if p_kind = 'invoice' then
          select jsonb_agg(jsonb_build_object(
            'description', l.description,
            'accountCode', a.code,
            'quantity', 1,
            'unitPrice', l.amount,
            'taxCode', public.tax_code_on(l.tax_code, v_run_date)
          ) order by l.line_no)
          into v_lines
          from public.recurring_template_lines l
          join public.accounts a on a.id = l.account_id
          where l.template_id = t.id;

          v_doc_id := public.save_invoice_draft(v_org, jsonb_build_object(
            'customerContactId', t.contact_id,
            'invoiceNumber', v_doc_num,
            'invoiceDate', v_run_date,
            'dueDate', v_due_date,
            'pricingMode', 'exclusive',
            'notes', t.notes,
            'lines', v_lines
          ));

          if t.auto_record then
            perform public.post_invoice(v_org, v_doc_id);
            insert into public.recurring_runs (org_id, template_id, kind, scheduled_on, status, invoice_id, doc_number)
            values (v_org, t.id, 'invoice', v_run_date, 'recorded', v_doc_id, v_doc_num);
            v_recorded := v_recorded + 1;
          else
            insert into public.recurring_runs (org_id, template_id, kind, scheduled_on, status, invoice_id, doc_number)
            values (v_org, t.id, 'invoice', v_run_date, 'draft', v_doc_id, v_doc_num);
          end if;
        else
          select trade_classification into v_trade from public.contacts where id = t.contact_id;
          v_ap := public.control_account(v_org, case when v_trade = 'non_trade' then 'non_trade_ap' else 'ap' end);

          insert into public.bills (
            org_id, contact_id, bill_number, bill_date, due_date, payable_account_id, status, notes,
            subtotal, tax_total, total, created_by
          )
          values (
            v_org, t.contact_id, v_doc_num, v_run_date, v_due_date, v_ap, 'draft', t.notes,
            t.subtotal, t.tax_total, t.total, auth.uid()
          )
          returning id into v_doc_id;

          insert into public.bill_lines (bill_id, line_no, org_id, description, account_id, quantity, unit_price, tax_code, amount, tax_amount)
          select v_doc_id, l.line_no, v_org, l.description, l.account_id, 1, l.amount,
                 public.tax_code_on(l.tax_code, v_run_date), l.amount,
                 round(l.amount * public.tax_rate(public.tax_code_on(l.tax_code, v_run_date)), 2)
          from public.recurring_template_lines l
          where l.template_id = t.id
          order by l.line_no;

          -- Recompute totals in case sst_8 fell back to sst_6 on pre-2024-03-01 dates.
          update public.bills set
            subtotal = coalesce((select sum(amount) from public.bill_lines where bill_id = v_doc_id), 0),
            tax_total = coalesce((select sum(tax_amount) from public.bill_lines where bill_id = v_doc_id), 0),
            total = coalesce((select sum(amount + tax_amount) from public.bill_lines where bill_id = v_doc_id), 0)
          where id = v_doc_id;

          if t.auto_record then
            perform public.post_draft_bill(v_org, v_doc_id);
            insert into public.recurring_runs (org_id, template_id, kind, scheduled_on, status, bill_id, doc_number)
            values (v_org, t.id, 'bill', v_run_date, 'recorded', v_doc_id, v_doc_num);
            v_recorded := v_recorded + 1;
          else
            insert into public.recurring_runs (org_id, template_id, kind, scheduled_on, status, bill_id, doc_number)
            values (v_org, t.id, 'bill', v_run_date, 'draft', v_doc_id, v_doc_num);
          end if;
        end if;

        v_generated := v_generated + 1;
        v_next_count := v_next_count + 1;
        v_next_date := public.recurring_next_date(t.start_date, t.frequency, t.interval_count, v_next_count);
        if (t.occurrences_limit is not null and v_next_count >= t.occurrences_limit) or (t.end_date is not null and v_next_date > t.end_date) then
          v_run_date := null;
          v_new_status := 'completed';
        else
          v_run_date := v_next_date;
          v_new_status := 'active';
        end if;
        update public.recurring_templates
        set occurrences_generated = v_next_count, next_run_on = v_run_date, status = v_new_status, updated_at = now()
        where id = t.id;
      exception
        when others then
          v_err := sqlerrm;
          insert into public.recurring_runs (org_id, template_id, kind, scheduled_on, status, doc_number, error)
          values (v_org, t.id, p_kind, v_run_date, 'failed', v_doc_num, left(v_err, 500));
          v_failed := v_failed + 1;
          exit;
      end;
    end loop;
  end loop;

  return jsonb_build_object('evaluated', v_evaluated, 'generated', v_generated, 'recorded', v_recorded, 'failed', v_failed);
end;
$$;

revoke all on function public.record_draft_bill(text, uuid) from public, anon;
revoke all on function public.delete_draft_bill(text, uuid) from public, anon;
revoke all on function public.create_recurring_template(text, jsonb) from public, anon;
revoke all on function public.set_recurring_status(text, uuid, text) from public, anon;
revoke all on function public.generate_due_recurring(text, text, date) from public, anon;

grant execute on function public.record_draft_bill(text, uuid) to authenticated;
grant execute on function public.delete_draft_bill(text, uuid) to authenticated;
grant execute on function public.create_recurring_template(text, jsonb) to authenticated;
